def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    giraffe_patches = image_patch.find("giraffe")

    if len(giraffe_patches) < 2:
        return image_patch

    giraffes_sorted_by_horizontal_center = sorted(giraffe_patches, key=lambda g: g.horizontal_center)
    closest_giraffes = giraffes_sorted_by_horizontal_center[:2]

    # Calculate the direction each giraffe is facing based on their vertical positions
    directions = []
    for i in range(len(closest_giraffes)):
        for j in range(i + 1, len(closest_giraffes)):
            if closest_giraffes[i].vertical_center < closest_giraffes[j].vertical_center:
                directions.append((i, "looking up"))
            elif closest_giraffes[i].vertical_center > closest_giraffes[j].vertical_center:
                directions.append((i, "looking down"))

    # Find the pair of giraffes that are looking in opposite directions
    for i, dir1 in enumerate(directions):
        for j, dir2 in enumerate(directions):
            if i != j and dir1[1] == "looking up" and dir2[1] == "looking down":
                return closest_giraffes[dir1[0]]

    return closest_giraffes[0]

